<?php declare(strict_types=1);
$taxHistory=array_reverse(($currentTax??$s)['history']);if(!$taxHistory)return;
$historyPages=(int)ceil(count($taxHistory)/20);$historyRaw=input($_GET,'period_tax_history_page','1');$historyValid=(!array_key_exists('period_tax_history_page',$_GET)||is_string($_GET['period_tax_history_page']))&&preg_match('/\A[1-9][0-9]{0,2}\z/D',$historyRaw)&&(int)$historyRaw<=$historyPages;$historyPage=$historyValid?(int)$historyRaw:1;
$historyUrl=static fn(int$page):string=>url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$taxPeriodId,'period_tax'=>'1','period_tax_history_page'=>(string)$page]);
?>
<details class="card" data-period-tax-history <?= array_key_exists('period_tax_history_page',$_GET)?'open':'' ?>><summary><?= e($taxText('Entscheidungen zu den Steuerwerten')) ?> (<?= count($taxHistory) ?>)</summary>
<?php if(!$historyValid): ?><p role="alert"><?= e($taxText('Verlaufsseite der Steuerwerte vollständig auswählen.')) ?></p><a class="btn btn-outline" href="<?= e($historyUrl(1)) ?>"><?= e($taxText('Verlauf neu öffnen')) ?></a><?php else: ?>
<?php foreach(array_slice($taxHistory,($historyPage-1)*20,20)as$h): ?><article><h3><?= e((new DateTimeImmutable($h['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' · '.$taxText($h['state']==='reviewed'?'Bestätigt':'Vorbereitet')) ?></h3><p><?= e($h['note']) ?></p><a class="btn btn-outline" data-tax-history-link="<?= (int)$h['revision'] ?>" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$taxPeriodId,'period_tax'=>'1','period_tax_original'=>(string)$h['revision'],'period_tax_original_sha256'=>$h['sha256']])) ?>"><?= e($taxText('Diesen ursprünglichen Ausgang lesen')) ?></a></article><?php endforeach ?>
<?php if($historyPages>1): ?><nav aria-label="<?= e($taxText('Verlauf der Steuerwerte')) ?>"><p><?= e($taxText('Seite')) ?> <?= $historyPage ?> / <?= $historyPages ?></p><?php if($historyPage>1): ?><a class="btn btn-outline" href="<?= e($historyUrl($historyPage-1)) ?>"><?= e($taxText('Neuere Entscheidungen')) ?></a><?php endif ?><?php if($historyPage<$historyPages): ?><a class="btn btn-outline" href="<?= e($historyUrl($historyPage+1)) ?>"><?= e($taxText('Frühere Entscheidungen')) ?></a><?php endif ?></nav><?php endif ?>
<?php endif ?></details>
